import{_ as t,o as e,c as d,a2 as r}from"./chunks/framework.RycU2wFZ.js";const g=JSON.parse('{"title":"AgentPay Python / Go 协议一致性测试报告 (T2.6 Conformance Report)","description":"","frontmatter":{},"headers":[],"relativePath":"specs/reports/protocol-conformance-report.md","filePath":"specs/reports/protocol-conformance-report.md","lastUpdated":1792399623000}'),c={name:"specs/reports/protocol-conformance-report.md"};function n(a,o,l,s,i,_){return e(),d("div",null,[...o[0]||(o[0]=[r('<h1 id="agentpay-python-go-协议一致性测试报告-t2-6-conformance-report" tabindex="-1">AgentPay Python / Go 协议一致性测试报告 (T2.6 Conformance Report) <a class="header-anchor" href="#agentpay-python-go-协议一致性测试报告-t2-6-conformance-report" aria-label="Permalink to &quot;AgentPay Python / Go 协议一致性测试报告 (T2.6 Conformance Report)&quot;">​</a></h1><blockquote><p><strong>报告版本</strong>：v2.0.0<br><strong>执行日期</strong>：2026-10-18<br><strong>测试状态</strong>：<strong>100% 通过 (PASSED)</strong><br><strong>执行环境</strong>：macOS (Darwin arm64), Python 3.12.7 (pytest 9.1.1), Go 1.24<br><strong>涉及核心规范</strong>：</p><ul><li><a href="https://github.com/open-agentpay/AgentPay/blob/main/specs/protocol-consistency-spec.md" target="_blank" rel="noreferrer"><code>specs/protocol-consistency-spec.md</code></a> (T1.3 统一协议契约)</li><li><a href="https://github.com/open-agentpay/AgentPay/blob/main/specs/conformance/protocol-errors.json" target="_blank" rel="noreferrer"><code>specs/conformance/protocol-errors.json</code></a> (统一错误码表与 Schema)</li><li><a href="https://github.com/open-agentpay/AgentPay/blob/main/specs/test-vectors/dual-path-protocol.json" target="_blank" rel="noreferrer"><code>specs/test-vectors/dual-path-protocol.json</code></a> (双轨协议一致性测试向量)</li><li><a href="https://github.com/open-agentpay/AgentPay/blob/main/specs/conformance/state-machine.json" target="_blank" rel="noreferrer"><code>specs/conformance/state-machine.json</code></a> (统一状态机模型)</li></ul></blockquote><hr><h2 id="_1-概述与测试目标" tabindex="-1">1. 概述与测试目标 <a class="header-anchor" href="#_1-概述与测试目标" aria-label="Permalink to &quot;1. 概述与测试目标&quot;">​</a></h2><p>为确保 AgentPay 的 <strong>Python 买方客户端（Buyer SDK）</strong> 与 <strong>Go 云原生网关（Go Gateway）</strong> 在数据面与控制面交互时行为完全同构，任务 <strong>T2.6 完成 Python/Go 一致性测试</strong> 对比了以下维度的跨语言同构性：</p><ol><li><strong>统一错误分类与响应信封（Canonical Error Taxonomy）</strong>：验证 Go 网关与 Python 客户端所使用的全量 17 个标准化错误码、HTTP 状态码、领域划分与 JSON 响应格式 1:1 对齐；</li><li><strong>双轨协议测试向量（Dual-Path Protocol Test Vectors）</strong>：验证 <code>TC_PROTO_01</code> 至 <code>TC_PROTO_06</code> 跨语言执行，在 x402 链上出题、虚拟钱包扣费、余额不足无静默降级、欠费冻结、幂等冲突等场景下的确定性裁定；</li><li><strong>状态机矩阵流转与守卫（State Machine &amp; Invariants）</strong>：在 Go 内部实现状态机引擎，验证其与 Python 侧状态迁移规则、终端不可变性、调度守卫（<code>INV_1_DISPATCH_GUARD</code>）、未知防重守卫（<code>INV_2_UNKNOWN_SUBMIT_GUARD</code>）与复合视图推导 100% 相同；</li><li><strong>端到端跨语言网络互操作性（Live HTTP Cross-Language Conformance）</strong>：启动 Go 网关独立进程与 Python 模拟后端，通过 Python <code>httpx</code> 客户端真实向 Go 网关发起网络请求，验证挑战解析、Bearer Token 虚拟钱包扣费、配置版本追踪标头注入、防双花防篡改冲突等全链路集成。</li></ol><hr><h2 id="_2-跨语言测试覆盖矩阵" tabindex="-1">2. 跨语言测试覆盖矩阵 <a class="header-anchor" href="#_2-跨语言测试覆盖矩阵" aria-label="Permalink to &quot;2. 跨语言测试覆盖矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>测试维度</th><th>测试套件与文件</th><th>测试用例数</th><th>结果</th><th>重点验证项</th></tr></thead><tbody><tr><td><strong>全量错误码对齐</strong></td><td><code>gateway-go/internal/x402/conformance_test.go</code><br><code>python/tests/unit/test_protocol_conformance_vectors.py</code></td><td>18 项</td><td><strong>PASS</strong></td><td>17 个 Canonical Error Code 状态码、Domain、Message 及标准 Wire Format Envelope 校验</td></tr><tr><td><strong>双轨协议测试向量</strong></td><td><code>specs/test-vectors/dual-path-protocol.json</code><br><code>gateway-go/internal/x402/conformance_test.go</code></td><td>6 项</td><td><strong>PASS</strong></td><td><code>TC_PROTO_01</code> ~ <code>TC_PROTO_06</code> 驱动测试，覆盖出题、选路、防降级、欠费、幂等冲突</td></tr><tr><td><strong>状态机矩阵与守卫</strong></td><td><code>gateway-go/internal/statemachine/engine_test.go</code><br><code>python/tests/unit/test_state_machine_matrix.py</code></td><td>42 项</td><td><strong>PASS</strong></td><td>35 个合法转移、非法转移拦截、终端状态不可变、双轨调度守卫、未知防重守卫、复合视图映射</td></tr><tr><td><strong>配置发布一致性</strong></td><td><code>specs/test-vectors/config-publishing.json</code><br><code>gateway-go/internal/rcu/snapshot_test.go</code><br><code>python/tests/unit/test_config_publishing.py</code></td><td>5 项</td><td><strong>PASS</strong></td><td><code>TC_CFG_01</code> ~ <code>TC_CFG_05</code>，静态校验矩阵、Canonical SHA-256 签名计算、版本回滚与容灾降级</td></tr><tr><td><strong>端到端进程级互操作</strong></td><td><code>python/tests/integration/test_cross_language_conformance.py</code></td><td>6 项</td><td><strong>PASS</strong></td><td>真实 Python 客户端向独立 Go Gateway 发起 HTTP 请求，解析 Challenge、钱包扣费、标头溯源、幂等与故障注入</td></tr></tbody></table><hr><h2 id="_3-测试用例执行与结果明细" tabindex="-1">3. 测试用例执行与结果明细 <a class="header-anchor" href="#_3-测试用例执行与结果明细" aria-label="Permalink to &quot;3. 测试用例执行与结果明细&quot;">​</a></h2><h3 id="_3-1-双轨协议测试向量结果-dual-path-vectors" tabindex="-1">3.1 双轨协议测试向量结果 (Dual-Path Vectors) <a class="header-anchor" href="#_3-1-双轨协议测试向量结果-dual-path-vectors" aria-label="Permalink to &quot;3.1 双轨协议测试向量结果 (Dual-Path Vectors)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>用例 ID</th><th>类别</th><th>输入特征</th><th>预期行为</th><th>Go 网关验证</th><th>Python SDK 验证</th><th>结论</th></tr></thead><tbody><tr><td><code>TC_PROTO_01</code></td><td>ONCHAIN_X402</td><td>匿名未认证 GET 请求</td><td>返回 402，带 <code>PAYMENT-REQUIRED</code> 标头，载荷符合 EIP-3009 结构</td><td>PASS (402, EIP-3009)</td><td>PASS (from_header 解析成功)</td><td><strong>一致</strong></td></tr><tr><td><code>TC_PROTO_02</code></td><td>WALLET_PAYMENT</td><td>携带有效 API Key</td><td>选用虚拟钱包扣费，执行 Hold 冻结，不触发链上出题</td><td>PASS (200, 扣除余额)</td><td>PASS (选路 wallet)</td><td><strong>一致</strong></td></tr><tr><td><code>TC_PROTO_03</code></td><td>WALLET_PAYMENT</td><td>虚拟钱包余额不足</td><td>返回 402 <code>ERR_WALLET_INSUFFICIENT_BALANCE</code>，<strong>严禁下发 PAYMENT-REQUIRED</strong></td><td>PASS (402, 无降级头)</td><td>PASS (402, 拒绝自动降级)</td><td><strong>一致</strong></td></tr><tr><td><code>TC_PROTO_04</code></td><td>WALLET_PAYMENT</td><td>钱包欠费冻结 (<code>frozen_arrears</code>)</td><td>拦截并返回 403 <code>ERR_WALLET_FROZEN</code></td><td>PASS (403, 阻断)</td><td>PASS (403, 阻断)</td><td><strong>一致</strong></td></tr><tr><td><code>TC_PROTO_05</code></td><td>ROUTING</td><td>wallet 路由收到链上签名</td><td>拦截并返回 403 <code>ERR_PAYMENT_METHOD_NOT_ALLOWED</code></td><td>PASS (403, 阻断)</td><td>PASS (403, 阻断)</td><td><strong>一致</strong></td></tr><tr><td><code>TC_PROTO_06</code></td><td>IDEMPOTENCY</td><td>相同幂等键附带不同载荷指纹</td><td>拦截并返回 409 <code>ERR_IDEMPOTENCY_CONFLICT</code></td><td>PASS (409, 阻断)</td><td>PASS (409, 阻断)</td><td><strong>一致</strong></td></tr></tbody></table><h3 id="_3-2-错误分类全量对齐-17-个错误码表" tabindex="-1">3.2 错误分类全量对齐 (17 个错误码表) <a class="header-anchor" href="#_3-2-错误分类全量对齐-17-个错误码表" aria-label="Permalink to &quot;3.2 错误分类全量对齐 (17 个错误码表)&quot;">​</a></h3><p>通过 <code>TestCanonicalErrorsIntegrityAgainstTaxonomy</code> 自动读取 <code>specs/conformance/protocol-errors.json</code> 与 Go 网关 <code>CanonicalErrorRegistry</code>：</p><ul><li><code>ERR_PAYMENT_REQUIRED</code> (402, PROTOCOL)</li><li><code>ERR_WALLET_INSUFFICIENT_BALANCE</code> (402, WALLET)</li><li><code>ERR_WALLET_FROZEN</code> (403, WALLET)</li><li><code>ERR_PAYMENT_METHOD_NOT_ALLOWED</code> (403, ROUTING)</li><li><code>ERR_POLICY_BUDGET_EXCEEDED</code> (403, POLICY)</li><li><code>ERR_POLICY_MAX_PER_TX</code> (403, POLICY)</li><li><code>ERR_POLICY_CIRCUIT_BROKEN</code> (429, POLICY)</li><li><code>ERR_API_KEY_INVALID</code> (401, AUTH)</li><li><code>ERR_API_KEY_SCOPE_DENIED</code> (403, AUTH)</li><li><code>ERR_TENANT_SUSPENDED</code> (403, TENANT)</li><li><code>ERR_SIGNATURE_INVALID</code> (401, CRYPTOGRAPHY)</li><li><code>ERR_NONCE_REPLAY</code> (409, SETTLEMENT)</li><li><code>ERR_IDEMPOTENCY_CONFLICT</code> (409, IDEMPOTENCY)</li><li><code>ERR_HOLD_EXPIRED</code> (408, WALLET)</li><li><code>ERR_UPSTREAM_TIMEOUT</code> (504, GATEWAY)</li><li><code>ERR_UPSTREAM_FAILED</code> (502, GATEWAY)</li><li><code>ERR_CONFIG_VERSION_EXPIRED</code> (409, CONFIG)</li></ul><p>全部错误码的状态码（HTTP Status）、业务领域（Domain）与响应信封（Wire Format Envelope）跨语言 100% 对齐。</p><h3 id="_3-3-状态机矩阵与安全守卫对齐" tabindex="-1">3.3 状态机矩阵与安全守卫对齐 <a class="header-anchor" href="#_3-3-状态机矩阵与安全守卫对齐" aria-label="Permalink to &quot;3.3 状态机矩阵与安全守卫对齐&quot;">​</a></h3><p>在 Go 侧建立 <code>gateway-go/internal/statemachine</code> 引擎并执行 <code>specs/conformance/state-machine.json</code>：</p><ol><li><strong>合法转移矩阵</strong>：35 个 (from, event, to) 状态迁移在 Go 与 Python 中产出完全一致的目标状态；</li><li><strong>终态不可变性（Terminal Immutability）</strong>：<code>settlement: confirmed/failed/released</code>、<code>fulfillment: succeeded/failed</code>、<code>payment_intent: settled/failed</code> 均严格拒绝后续修改事件；</li><li><strong>双轨调度守卫（<code>INV_1_DISPATCH_GUARD</code>）</strong>： <ul><li>链上路径：必须满足 <code>settlement == confirmed</code> 才允许向上游履约分发；</li><li>钱包路径：必须满足 <code>settlement == held</code>（已成功冻结额度）才允许向上游履约分发；</li></ul></li><li><strong>未知防重提交守卫（<code>INV_2_UNKNOWN_SUBMIT_GUARD</code>）</strong>： <ul><li>当 <code>settlement == unknown</code> 时，严格禁止盲目重新 submit；仅当处于 <code>not_started</code> 时才允许提交；</li></ul></li><li><strong>复合视图映射（Composite Views）</strong>：9 种状态组合推导出的用户端状态（<code>WALLET_HOLD_PROCESSING</code>, <code>SETTLEMENT_IN_PROGRESS</code>, <code>FULFILLMENT_IN_PROGRESS</code>, <code>COMPLETED</code>, <code>SETTLED_FULFILLMENT_FAILED_REFUND_REQUIRED</code>, <code>SETTLED_FULFILLMENT_UNKNOWN_NEEDS_REVIEW</code>, <code>RELEASED_UNBILLED</code>, <code>PAYMENT_FAILED</code>）与 Python 实现 100% 同构。</li></ol><hr><h2 id="_4-发现并修复的行为差异清单" tabindex="-1">4. 发现并修复的行为差异清单 <a class="header-anchor" href="#_4-发现并修复的行为差异清单" aria-label="Permalink to &quot;4. 发现并修复的行为差异清单&quot;">​</a></h2><p>在一致性测试落地过程中，发现并修复了以下行为差异：</p><ol><li><strong>Canonical Error Taxonomy 命名与别名同构</strong>： <ul><li><em>差异</em>：Go 网关此前定义了 <code>ERR_NONCE_ALREADY_USED</code> 与 <code>ERR_UPSTREAM_BAD_GATEWAY</code>，而标准规范定义为 <code>ERR_NONCE_REPLAY</code> (409, SETTLEMENT) 与 <code>ERR_UPSTREAM_FAILED</code> (502, GATEWAY)，且缺少 <code>ERR_HOLD_EXPIRED</code> 与 <code>ERR_CONFIG_VERSION_EXPIRED</code>；</li><li><em>修复</em>：完善 <code>gateway-go/internal/x402/errors.go</code>，补齐全量 17 个错误码及其 Actionable 字段，并设立向后兼容别名保证已有模块零破坏。</li></ul></li><li><strong>出题 Network 动态化与 Fallback 机制</strong>： <ul><li><em>差异</em>：Go 网关原先在下发 402 challenge 时写死了 <code>&quot;eip155:84532&quot;</code>，未读取路由定义中的 <code>route.Network</code>；</li><li><em>修复</em>：在 <code>rcu.RouteConfig</code> 与 <code>config.RouteDefinition</code> 中增加 <code>Network</code> 字段，并在出题时优先取路由配置的 <code>route.Network</code>，空值回退至全局 <code>cfg.Settlement.DefaultNetwork</code>（如 <code>eip155:421614</code> Arbitrum Sepolia）。</li></ul></li><li><strong>大小写不敏感标头与 EVM 地址比较</strong>： <ul><li><em>差异</em>：Python 字典键查找对 HTTP Header 大小写敏感，导致断言 <code>x-agentpay-config-version</code> 偶现空指针；EVM 地址校验在 Python SDK 规范化为小写，而 Go 原样透传；</li><li><em>修复</em>：端到端测试与客户端逻辑统一采用大小写不敏感（RFC 7230 兼容）标头提取与以太坊地址比较。</li></ul></li><li><strong>测试钱包预设与隔离</strong>： <ul><li><em>优化</em>：在 <code>gateway-go/internal/server</code> 默认构造中内置激活、余额不足、欠费冻结三类预设账户，便于任何本地开发工具与端到端跨语言测试即开即测。</li></ul></li></ol><hr><h2 id="_5-验收结论" tabindex="-1">5. 验收结论 <a class="header-anchor" href="#_5-验收结论" aria-label="Permalink to &quot;5. 验收结论&quot;">​</a></h2><p>全仓测试验证结果：</p><ul><li><strong>Python 测试</strong>：373 项测试（含 6 项端到端跨语言测试）100% 通过（PASS）；</li><li><strong>Go 测试</strong>：全量单元、状态机矩阵与集成测试 100% 通过（PASS）；</li><li><strong>测试向量验证</strong>：<code>specs/test-vectors</code> 下各 JSON 跨语言测试向量全部绿灯；</li><li><strong>代码规范</strong>：<code>ruff check</code> 与 <code>ruff format --check</code> 无任何警告。</li></ul><p><strong>T2.6 完成 Python/Go 一致性测试验收标准全部满足，正式交付完成。</strong></p>',29)])])}const h=t(c,[["render",n]]);export{g as __pageData,h as default};
